package com.yuyutian.mytools.gateway.service;
import com.yuyutian.mytools.gateway.config.GatewayProperties;import com.yuyutian.mytools.gateway.model.ReaderSearchGatewayModels.*;import org.junit.jupiter.api.Test;import org.springframework.http.MediaType;import org.springframework.test.web.client.MockRestServiceServer;import org.springframework.web.client.RestTemplate;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;import static org.springframework.http.HttpMethod.POST;import static org.springframework.test.web.client.match.MockRestRequestMatchers.*;import static org.springframework.test.web.client.response.MockRestResponseCreators.withSuccess;
class ReaderGatewayClientTest {@Test void shouldCreateOwnerBoundSearchWithoutExposingTaskId(){RestTemplate template=new RestTemplate();MockRestServiceServer server=MockRestServiceServer.bindTo(template).build();UUID id=UUID.randomUUID();server.expect(requestTo("http://reader/api/v1/book-searches")).andExpect(method(POST)).andExpect(content().json("{\"ownerId\":55,\"idempotencyKey\":\"search-1\",\"keyword\":\"Book\",\"mode\":\"FUZZY\",\"page\":1,\"sources\":[{\"id\":\"source\",\"name\":\"Source\",\"url\":\"https://source.example\",\"revision\":1,\"snapshot\":{}}]}")).andRespond(withSuccess("{\"id\":\""+id+"\",\"taskId\":\""+UUID.randomUUID()+"\",\"status\":\"QUEUED\",\"keyword\":\"Book\",\"mode\":\"FUZZY\",\"page\":1,\"completedShards\":0,\"failedShards\":0,\"totalShards\":0,\"results\":[],\"createdAt\":\"2026-08-24T00:00:00Z\",\"updatedAt\":\"2026-08-24T00:00:00Z\"}",MediaType.APPLICATION_JSON));var result=new ReaderGatewayClient(template,properties()).createSearch(55L,new CreateSearch("search-1","Book","FUZZY",1,List.of(new SourceSnapshot("source","Source","https://source.example",1,Map.of()))),"correlation");assertThat(result.id()).isEqualTo(id);assertThat(result.toString()).doesNotContain("taskId");server.verify();}
 @Test void shouldInjectOwnerIntoRuntimeCatalog(){RestTemplate template=new RestTemplate();MockRestServiceServer server=MockRestServiceServer.bindTo(template).build();server.expect(requestTo("http://reader/api/v1/source-runtime/catalog")).andExpect(method(POST)).andExpect(content().json("{\"ownerId\":55,\"sourceUrl\":\"https://source.example\",\"bookUrl\":\"https://book.example\"}")).andRespond(withSuccess("{\"name\":\"Book\",\"chapters\":[]}",MediaType.APPLICATION_JSON));var value=new ReaderGatewayClient(template,properties()).sourceCatalog(55L,"https://source.example","https://book.example","correlation");assertThat(value.get("name")).isEqualTo("Book");server.verify();}
 @Test void shouldCreateOwnerBoundAudiobookVoiceRevision(){RestTemplate template=new RestTemplate();MockRestServiceServer server=MockRestServiceServer.bindTo(template).build();UUID sourceId=UUID.randomUUID();UUID revisionId=UUID.randomUUID();server.expect(requestTo("http://reader/api/v1/audiobook-generations/"+sourceId+"/voice-revisions?ownerId=55")).andExpect(method(POST)).andExpect(content().json("{\"idempotencyKey\":\"revision-1\",\"roleKey\":\"CHARACTER:Lin\",\"provider\":\"VOLCENGINE\",\"voiceType\":\"voice-alt\"}")).andRespond(withSuccess("{\"id\":\""+revisionId+"\",\"status\":\"QUEUED\",\"currentStage\":\"SYNTHESIZING\",\"mode\":\"REPAIR\",\"generationVersion\":2,\"requestedChapterCount\":2,\"completedChapterCount\":0,\"failedChapterCount\":0,\"errorCode\":null,\"createdAt\":\"2026-09-06T00:00:00Z\",\"updatedAt\":\"2026-09-06T00:00:00Z\"}",MediaType.APPLICATION_JSON));var result=new ReaderGatewayClient(template,properties()).createAudiobookVoiceRevision(55L,sourceId,new com.yuyutian.mytools.gateway.model.AudiobookGatewayModels.CreateAudiobookVoiceRevision("revision-1","CHARACTER:Lin","VOLCENGINE","voice-alt"),"correlation");assertThat(result.id()).isEqualTo(revisionId);server.verify();}
 @Test void shouldCreateOwnerBoundAudiobookSpeakerRevision(){RestTemplate template=new RestTemplate();MockRestServiceServer server=MockRestServiceServer.bindTo(template).build();UUID sourceId=UUID.randomUUID();UUID revisionId=UUID.randomUUID();server.expect(requestTo("http://reader/api/v1/audiobook-generations/"+sourceId+"/speaker-revisions?ownerId=55")).andExpect(method(POST)).andExpect(content().json("{\"idempotencyKey\":\"speaker-revision-1\",\"chapterIndex\":2,\"sequenceNumber\":4,\"speakerKind\":\"CHARACTER\",\"speakerCanonicalName\":\"Chen\"}")).andRespond(withSuccess("{\"id\":\""+revisionId+"\",\"status\":\"QUEUED\",\"currentStage\":\"SYNTHESIZING\",\"mode\":\"REPAIR\",\"generationVersion\":2,\"requestedChapterCount\":2,\"completedChapterCount\":0,\"failedChapterCount\":0,\"errorCode\":null,\"createdAt\":\"2026-09-06T00:00:00Z\",\"updatedAt\":\"2026-09-06T00:00:00Z\"}",MediaType.APPLICATION_JSON));var result=new ReaderGatewayClient(template,properties()).createAudiobookSpeakerRevision(55L,sourceId,new com.yuyutian.mytools.gateway.model.AudiobookGatewayModels.CreateAudiobookSpeakerRevision("speaker-revision-1",2,4,"CHARACTER","Chen"),"correlation");assertThat(result.id()).isEqualTo(revisionId);server.verify();}
 @Test void shouldCreateAndReadOwnerBoundAudiobookPronunciationRevision(){RestTemplate template=new RestTemplate();MockRestServiceServer server=MockRestServiceServer.bindTo(template).build();UUID sourceId=UUID.randomUUID();UUID revisionId=UUID.randomUUID();server.expect(requestTo("http://reader/api/v1/audiobook-generations/"+sourceId+"/pronunciation-revisions?ownerId=55")).andExpect(method(POST)).andExpect(content().json("{\"idempotencyKey\":\"pronunciation-revision-1\",\"term\":\"银行\",\"pinyin\":\"yin2 hang2\"}")).andRespond(withSuccess("{\"id\":\""+revisionId+"\",\"status\":\"QUEUED\",\"currentStage\":\"PREPARING_PRONUNCIATION\",\"mode\":\"REPAIR\",\"generationVersion\":2,\"requestedChapterCount\":2,\"completedChapterCount\":0,\"failedChapterCount\":0,\"errorCode\":null,\"createdAt\":\"2026-09-06T00:00:00Z\",\"updatedAt\":\"2026-09-06T00:00:00Z\"}",MediaType.APPLICATION_JSON));server.expect(requestTo("http://reader/api/v1/audiobook-generations/"+revisionId+"/pronunciations?ownerId=55")).andExpect(method(org.springframework.http.HttpMethod.GET)).andRespond(withSuccess("{\"generationId\":\""+revisionId+"\",\"fingerprintSha256\":\""+"a".repeat(64)+"\",\"entries\":[{\"term\":\"银行\",\"pinyin\":\"yin2 hang2\"}]}",MediaType.APPLICATION_JSON));var client=new ReaderGatewayClient(template,properties());var revision=client.createAudiobookPronunciationRevision(55L,sourceId,new com.yuyutian.mytools.gateway.model.AudiobookGatewayModels.CreateAudiobookPronunciationRevision("pronunciation-revision-1","银行","yin2 hang2"),"correlation");var dictionary=client.audiobookPronunciationDictionary(55L,revisionId,"correlation");assertThat(revision.id()).isEqualTo(revisionId);assertThat(dictionary.entries()).singleElement().satisfies(entry->{assertThat(entry.term()).isEqualTo("银行");assertThat(entry.pinyin()).isEqualTo("yin2 hang2");});server.verify();}
 @Test void shouldPreserveStableReaderRejection(){RestTemplate template=new RestTemplate();MockRestServiceServer server=MockRestServiceServer.bindTo(template).build();UUID id=UUID.randomUUID();server.expect(requestTo("http://reader/api/v1/audiobook-generations/"+id+"/retry?ownerId=55")).andExpect(method(POST)).andRespond(org.springframework.test.web.client.response.MockRestResponseCreators.withStatus(org.springframework.http.HttpStatus.TOO_MANY_REQUESTS).contentType(MediaType.APPLICATION_JSON).body("{\"code\":\"READER_028\",\"message\":\"ignored\"}"));org.assertj.core.api.Assertions.assertThatThrownBy(()->new ReaderGatewayClient(template,properties()).retryAudiobookGeneration(55L,id,"correlation")).isInstanceOfSatisfying(GatewayReaderRejectedException.class,value->{assertThat(value.statusCode()).isEqualTo(org.springframework.http.HttpStatus.TOO_MANY_REQUESTS);assertThat(value.errorCode()).isEqualTo("READER_028");});server.verify();}
 private GatewayProperties properties(){return new GatewayProperties(GatewayProperties.IdentityMode.LEGACY,false,true,Set.of(55L),false,Set.of(),false,Set.of(),"http://mytools","http://identity","http://reader","http://drive","http://download","gateway-token","identity-token","reader-token","drive-token","download-token",1000,3000,false,"","",false,"","");}}
